import{_ as o,a0 as l,w as r,s as p,ao as d,I as n,x as t,a1 as i,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"每個安卓開發初學者應該瞭解的 12 個技巧 | LCTT x X-CMD","titleTemplate":false,"description":"每個安卓開發初學者應該瞭解的 12 個技巧 | LCTT (201710) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每個安卓開發初學者應該瞭解的 12 個技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每個安卓開發初學者應該瞭解的 12 個技巧 | LCTT (201710) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201710/20170929 12 Practices every Android Development Beginner should know — Part 1","title":"每個安卓開發初學者應該瞭解的 12 個技巧","tag":"201710","desc":""},"relativePath":"201710/20170929 12 Practices every Android Development Beginner should know — Part 1.md","filePath":"[post].md"}'),h={name:"201710/20170929 12 Practices every Android Development Beginner should know — Part 1.md"};function g(c,e,u,b,k,m){const a=l("Link");return r(),p("div",null,[e[24]||(e[24]=d(`<h1 id="每個安卓開發初學者應該瞭解的-12-個技巧" tabindex="-1">每個安卓開發初學者應該瞭解的 12 個技巧 <a class="header-anchor" href="#每個安卓開發初學者應該瞭解的-12-個技巧" aria-label="Permalink to “每個安卓開發初學者應該瞭解的 12 個技巧”">​</a></h1><blockquote><p>一次掌握一個技巧，更好地學習安卓</p></blockquote><p><img src="https://cdn-images-1.medium.com/max/800/1*RwCbsNdykQYr6vDa6aCGKQ.jpeg" alt=""></p><p>距離安迪·魯賓和他的團隊着手開發一個希望顛覆傳統手機操作模式的操作系統已經過去 12 年了，這套系統有可能讓手機或者智能機給消費者以及軟件開發人員帶來全新的體驗。之前的智能機僅限於收發短信和查看電子郵件（當然還可以打電話），給用户和開發者帶來很大的限制。</p><p>安卓，作為打破這個枷鎖的系統，擁有非常優秀的框架設計，給大家提供的不僅僅是一組有限的功能，更多的是自由的探索。有人會説 iPhone 才是手機產業的顛覆產品，不過我們説的不是 iPhone 有多麼酷（或者多麼貴，是吧？），它還是有限制的，而這是我們從來都不希望有的。</p><p>不過，就像本大叔説的，能力越大責任越大，我們也需要更加認真對待安卓應用的設計方式。我看到很多教程都忽略了向初學者傳遞這個理念，在動手之前請先充分理解系統架構。他們只是把一堆的概念和代碼丟給讀者，卻沒有解釋清楚相關的優缺點，它們對系統的影響，以及該用什麼不該用什麼等等。</p><p>在這篇文章裏，我們將介紹一些初學者以及中級開發人員都應該掌握的技巧，以幫助更好地理解安卓框架。後續我們還會在這個系列裏寫更多這樣的關於實用技巧的文章。我們開始吧。</p><h3 id="_1、-id-和-id-的區別" tabindex="-1">1、 <code>@+id</code> 和 <code>@id</code> 的區別 <a class="header-anchor" href="#_1、-id-和-id-的區別" aria-label="Permalink to “1、 @+id 和 @id 的區別”">​</a></h3><p>要在 Java 代碼裏訪問一個圖形控件（或組件），或者是要讓它成為其他控件的依賴，我們需要一個唯一的值來引用它。這個唯一值用 <code>android:id</code> 屬性來定義，本質上就是把用户提供的 id 附加到 <code>@+id/</code> 後面，寫入到 <em>id 資源文件</em>，供其他控件使用。一個 Toolbar 的 id 可以這樣定義，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>android:id=&quot;@+id/toolbar&quot;</span></span></code></pre></div><p>然後這個 id 值就能被 <code>findViewById(…)</code> 識別，這個函數會在資源文件裏查找 id，或者直接從 R.id 路徑引用，然後返回所查找的 View 的類型。</p><p>而另一種，<code>@id</code>，和 <code>findViewById(…)</code> 行為一樣 - 也會根據提供的 id 查找組件，不過僅限於佈局時使用。一般用來佈置相關控件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>android:layout_below=&quot;@id/toolbar&quot;</span></span></code></pre></div><h3 id="_2、-使用-string-資源為-xml-提供字符串" tabindex="-1">2、 使用 <code>@string</code> 資源為 XML 提供字符串 <a class="header-anchor" href="#_2、-使用-string-資源為-xml-提供字符串" aria-label="Permalink to “2、 使用 @string 資源為 XML 提供字符串”">​</a></h3><p>簡單來説，就是不要在 XML 裏直接用字符串。原因很簡單。當我們在 XML 裏直接使用了字符串，我們一般會在其它地方再次用到同樣的字符串。想像一下當我們需要在不同的地方調整同一個字符串的噩夢，而如果使用字符串資源就只改一個地方就夠了。另一個好處是，使用資源文件可以提供多國語言支持，因為可以為不同的語言創建相應的字符串資源文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>android:text=&quot;My Awesome Application&quot;</span></span></code></pre></div><p>當你直接使用字符串時，你會在 Android Studio 裏收到警告，提示説應該把寫死的字符串改成字符串資源。可以點擊這個提示，然後按下 <code>ALT + ENTER</code> 打開字符串編輯。你也可以直接打開 <code>res</code> 目錄下的 <code>values</code> 目錄裏的 <code>strings.xml</code> 文件，然後像下面這樣聲明一個字符串資源。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;string name=&quot;app_name&quot;&gt;My Awesome Application&lt;/string&gt;</span></span></code></pre></div><p>然後用它來替換寫死的字符串，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>android:text=&quot;@string/app_name&quot;</span></span></code></pre></div><h3 id="_3、-使用-android-和-attr-常量" tabindex="-1">3、 使用 <code>@android</code> 和 <code>?attr</code> 常量 <a class="header-anchor" href="#_3、-使用-android-和-attr-常量" aria-label="Permalink to “3、 使用 @android 和 ?attr 常量”">​</a></h3><p>儘量使用系統預先定義的常量而不是重新聲明。舉個例子，在佈局中有幾個地方要用白色或者 #ffffff 顏色值。不要每次都直接用 #ffffff 數值，也不要自己為白色重新聲明資源，我們可以直接用這個，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@android:color/white</span></span></code></pre></div><p>安卓預先定義了很多常用的顏色常量，比如白色，黑色或粉色。最經典的應用場景是透明色：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>@android:color/transparent</span></span></code></pre></div><p>另一個引用常量的方式是 <code>?attr</code>，用來將預先定義的屬性值賦值給不同的屬性。舉個自定義 Toolbar 的例子。這個 Toolbar 需要定義寬度和高度。寬度通常可以設置為 <code>MATCH_PARENT</code>，但高度呢？我們大多數人都沒有注意設計指導，只是簡單地隨便設置一個看上去差不多的值。這樣做不對。不應該隨便自定義高度，而應該這樣做，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>android:layout_height=&quot;?attr/actionBarSize&quot;</span></span></code></pre></div><p><code>?attr</code> 的另一個應用是點擊視圖時畫水波紋效果。<code>SelectableItemBackground</code> 是一個預定義的 drawable，任何視圖需要增加波紋效果時可以將它設為背景：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>android:background=&quot;?attr/selectableItemBackground&quot;</span></span></code></pre></div><p>也可以用這個：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>android:background=&quot;?attr/selectableItemBackgroundBorderless&quot;</span></span></code></pre></div><p>來顯示無邊框波紋。</p><h3 id="_4、-sp-和-dp-的區別" tabindex="-1">4、 SP 和 DP 的區別 <a class="header-anchor" href="#_4、-sp-和-dp-的區別" aria-label="Permalink to “4、 SP 和 DP 的區別”">​</a></h3><p>雖然這兩個沒有本質上的區別，但知道它們是什麼以及在什麼地方適合用哪個很重要。</p><p>SP 的意思是縮放無關像素，一般建議用於 TextView，首先文字不會因為顯示密度不同而顯示效果不一樣，另外 TextView 的內容還需要根據用户設定做拉伸，或者只調整字體大小。</p><p>其他需要定義尺寸和位置的地方，可以使用 DP，也就是密度無關像素。之前説過，DP 和 SP 的性質是一樣的，只是 DP 會根據顯示密度自動拉伸，因為安卓系統會動態計算實際顯示的像素，這樣就可以讓使用 DP 的組件在不同顯示密度的設備上都可以擁有相同的顯示效果。</p><h3 id="_5、-drawable-和-mipmap-的應用" tabindex="-1">5、 Drawable 和 Mipmap 的應用 <a class="header-anchor" href="#_5、-drawable-和-mipmap-的應用" aria-label="Permalink to “5、 Drawable 和 Mipmap 的應用”">​</a></h3><p>這兩個最讓人困惑的是 - drawable 和 mipmap 有多少差異？</p><p>雖然這兩個好像有同樣的用途，但它們設計目的不一樣。mipmap 是用來儲存圖標的，而 drawable 用於任何其他格式。我們可以看一下系統內部是如何使用它們的，就知道為什麼不能混用了。</p><p>你可以看到你的應用裏有幾個 mipmap 和 drawable 目錄，每一個分別代表不同的顯示分辨率。當系統從 drawable 目錄讀取資源時，只會根據當前設備的顯示密度選擇確定的目錄。然而，在讀取 mipmap 時，系統會根據需要選擇合適的目錄，而不僅限於當前顯示密度，主要是因為有些啓動器會故意顯示較大的圖標，所以系統會使用較大分辨率的資源。</p><p>總之，用 mipmap 來存放圖標或標記圖片，可以在不同顯示密度的設備上看到分辨率變化，而其它根據需要顯示的圖片資源都用 drawable。</p><p>比如説，Nexus 5 的顯示分辨率是 xxhdpi。當我們把圖標放到 <code>mipmap</code> 目錄裏時，所有 <code>mipmap</code> 目錄都將讀入內存。而如果放到 drawable 裏，只有 <code>drawable-xxhdpi</code> 目錄會被讀取，其他目錄都會被忽略。</p><h3 id="_6、-使用矢量圖形" tabindex="-1">6、 使用矢量圖形 <a class="header-anchor" href="#_6、-使用矢量圖形" aria-label="Permalink to “6、 使用矢量圖形”">​</a></h3><p>為了支持不同顯示密度的屏幕，將同一個資源的多個版本（大小）添加到項目裏是一個很常見的技巧。這種方式確實有用，不過它也會帶來一定的性能開支，比如更大的 apk 文件以及額外的開發工作。為了消除這種影響，谷歌的安卓團隊發佈了新增的矢量圖形。</p><p>矢量圖形是用 XML 描述的 SVG（可拉伸矢量圖形），是用點、直線和曲線組合以及填充顏色繪製出的圖形。正因為矢量圖形是由點和線動態畫出來的，在不同顯示密度下拉伸也不會損失分辨率。而矢量圖形帶來的另一個好處是更容易做動畫。往一個 AnimatedVectorDrawable 文件裏添加多個矢量圖形就可以做出動畫，而不用添加多張圖片然後再分別處理。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;vector xmlns:android=&quot;http://schemas.android.com/apk/res/android&quot;</span></span>
<span class="line"><span>    android:width=&quot;24dp&quot; </span></span>
<span class="line"><span>    android:height=&quot;24dp&quot; </span></span>
<span class="line"><span>    android:viewportWidth=&quot;24.0&quot; </span></span>
<span class="line"><span>    android:viewportHeight=&quot;24.0&quot;&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &lt;path android:fillColor=&quot;#69cdff&quot; android:pathData=&quot;M3,18h18v-2L3,16v2zM3,13h18v-2L3,11v2zM3,6v2h18L21,6L3,6z&quot;/&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;/vector&gt;</span></span></code></pre></div><p>上面的向量定義可以畫出下面的圖形，</p><p><img src="https://cdn-images-1.medium.com/max/600/1*KGmMIhrQR0UyrpIP_niEZw.png" alt=""></p><p>要在你的安卓項目裏添加矢量圖形，可以右鍵點擊你項目裏的應用模組，然後選擇 New &gt;&gt; Vector Assets。然後會打開 Assets Studio，你可以有兩種方式添加矢量圖形。第一種是從 Material 圖標裏選擇，另一種是選擇本地的 SVG 或 PSD 文件。</p>`,49)),n("p",null,[e[1]||(e[1]=t("谷歌建議與應用相關都使用 Material 圖標，來保持安卓的連貫性和統一體驗。",-1)),i(a,{href:"https://material.io/icons/"},{default:s(()=>[...e[0]||(e[0]=[t("這裏",-1)])]),_:1}),e[2]||(e[2]=t("有全部圖標，記得看一下。",-1))]),e[25]||(e[25]=d(`<h3 id="_7、-設定邊界的開始和結束" tabindex="-1">7、 設定邊界的開始和結束 <a class="header-anchor" href="#_7、-設定邊界的開始和結束" aria-label="Permalink to “7、 設定邊界的開始和結束”">​</a></h3><p>這是人們最容易忽略的地方之一。邊界！增加邊界當然很簡單，但是如果要考慮支持很舊的平台呢？</p><p>邊界的“開始”和“結束”分別是“左”和“右”的超集，所以如果應用的 <code>minSdkVersion</code> 是 17 或更低，邊界和填充的“開始”和“結束”定義是舊的“左”/“右”所需要的。在那些沒有定義“開始”和“結束”的系統上，這兩個定義可以被安全地忽略。可以像下面這樣聲明：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>android:layout_marginEnd=&quot;20dp&quot;</span></span>
<span class="line"><span>android:paddingStart=&quot;20dp&quot;</span></span></code></pre></div><h3 id="_8、-使用-getter-setter-生成工具" tabindex="-1">8、 使用 Getter/Setter 生成工具 <a class="header-anchor" href="#_8、-使用-getter-setter-生成工具" aria-label="Permalink to “8、 使用 Getter/Setter 生成工具”">​</a></h3><p>在創建一個容器類（只是用來簡單的存放一些變量數據）時很煩的一件事情是寫多個 getter 和 setter，複製/粘貼該方法的主體再為每個變量重命名。</p><p>幸運的是，Android Studio 有一個解決方法。可以這樣做，在類裏聲明你需要的所有變量，然後打開 Toolbar &gt;&gt; Code。快捷方式是 <code>ALT + Insert</code>。點擊 Code 會顯示 Generate，點擊它會出來很多選項，裏面有 Getter 和 Setter 選項。在保持焦點在你的類頁面然後點擊，就會為當前類添加所有的 getter 和 setter（有需要的話可以再去之前的窗口操作）。很爽吧。</p><h3 id="_9、-使用-override-implement-生成工具" tabindex="-1">9、 使用 Override/Implement 生成工具 <a class="header-anchor" href="#_9、-使用-override-implement-生成工具" aria-label="Permalink to “9、 使用 Override/Implement 生成工具”">​</a></h3><p>這是另一個很好用的生成工具。自定義一個類然後再擴展很容易，但是如果要擴展你不熟悉的類呢。比如説 PagerAdapter，你希望用 ViewPager 來展示一些頁面，那就需要定製一個 PagerAdapter 並實現它的重載方法。但是具體有哪些方法呢？Android Studio 非常貼心地為自定義類強行添加了一個構造函數，或者可以用快捷鍵（<code>ALT + Enter</code>），但是父類 PagerAdapter 裏的其他（虛擬）方法需要自己手動添加，我估計大多數人都覺得煩。</p><p>要列出所有可以重載的方法，可以點擊 Code &gt;&gt; Generate and Override methods 或者 Implement methods，根據你的需要。你還可以為你的類選擇多個方法，只要按住 Ctrl 再選擇方法，然後點擊 OK。</p><h3 id="_10、-正確理解-context" tabindex="-1">10、 正確理解 Context <a class="header-anchor" href="#_10、-正確理解-context" aria-label="Permalink to “10、 正確理解 Context”">​</a></h3><p>Context 有點恐怖，我估計許多初學者從沒有認真理解過 Context 類的結構 - 它是什麼，為什麼到處都要用到它。</p><p>簡單地説，它將你能從屏幕上看到的所有內容都整合在一起。所有的視圖（或者它們的擴展）都通過 Context 綁定到當前的環境。Context 用來管理應用層次的資源，比如説顯示密度，或者當前的關聯活動。活動、服務和應用都實現了 Context 類的接口來為其他關聯組件提供內部資源。舉個添加到 MainActivity 的 TextView 的例子。你應該注意到了，在創建一個對象的時候，TextView 的構造函數需要 Context 參數。這是為了獲取 TextView 裏定義到的資源。比如説，TextView 需要在內部用到 Roboto 字體。這樣的話，TextView 需要 Context。而且在我們將 Context（或者 <code>this</code>）傳遞給 TextView 的時候，也就是告訴它綁定當前活動的生命週期。</p><p>另一個 Context 的關鍵應用是初始化應用層次的操作，比如初始化一個庫。庫的生命週期和應用是不相關的，所以它需要用 <code>getApplicationContext()</code> 來初始化，而不是用 <code>getContext</code> 或 <code>this</code> 或 <code>getActivity()</code>。掌握正確使用不同 Context 類型非常重要，可以避免內存泄漏。另外，要用到 Context 來啓動一個活動或服務。還記得 <code>startActivity(…)</code> 嗎？當你需要在一個非活動類裏切換活動時，你需要一個 Context 對象來調用 <code>startActivity</code> 方法，因為它是 Context 類的方法，而不是 Activity 類。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>getContext().startActivity(getContext(), SecondActivity.class);</span></span></code></pre></div>`,15)),n("p",null,[e[5]||(e[5]=t("如果你想了解更多 Context 的行為，可以看看",-1)),i(a,{href:"https://blog.mindorks.com/understanding-context-in-android-application-330913e32514"},{default:s(()=>[...e[3]||(e[3]=[t("這裏",-1)])]),_:1}),e[6]||(e[6]=t("或",-1)),i(a,{href:"https://developer.android.com/reference/android/content/Context.html"},{default:s(()=>[...e[4]||(e[4]=[t("這裏",-1)])]),_:1}),e[7]||(e[7]=t("。第一個是一篇關於 Context 的很好的文章，介紹了在哪些地方要用到它。而另一個是安卓關於 Context 的文檔，全面介紹了所有的功能 - 方法，靜態標識以及更多。",-1))]),e[26]||(e[26]=d('<h3 id="獎勵-1-格式化代碼" tabindex="-1">獎勵 #1: 格式化代碼 <a class="header-anchor" href="#獎勵-1-格式化代碼" aria-label="Permalink to “獎勵 #1: 格式化代碼”">​</a></h3><p>有人會不喜歡整齊，統一格式的代碼嗎？好吧，幾乎我們每一個人，在寫一個超過 1000 行的類的時候，都希望我們的代碼能有合適的結構。而且，並不僅僅大的類才需要格式化，每一個小模組類也需要讓代碼保持可讀性。</p><p>使用 Android Studio，或者任何 JetBrains IDE，你都不需要自己手動整理你的代碼，像增加縮進或者 = 之前的空格。就按自己希望的方式寫代碼，在想要格式化的時候，如果是 Windows 系統可以按下 <code>ALT + CTRL + L</code>，Linux 系統按下 <code>ALT + CTRL + SHIFT + L</code>。<em>代碼就自動格式化好了</em></p><h3 id="獎勵-2-使用庫" tabindex="-1">獎勵 #2: 使用庫 <a class="header-anchor" href="#獎勵-2-使用庫" aria-label="Permalink to “獎勵 #2: 使用庫”">​</a></h3><p>面向對象編程的一個重要原則是增加代碼的可重用性，或者説減少重新發明輪子的習慣。很多初學者錯誤地遵循了這個原則。這條路有兩個方向，</p><ul><li>不用任何庫，自己寫所有的代碼。</li><li>用庫來處理所有事情。</li></ul><p>不管哪個方向走到底都是不對的。如果你徹底選擇第一個方向，你將消耗大量的資源，僅僅是為了滿足自己擁有一切的驕傲。很可能你的代碼沒有做過替代庫那麼多的測試，從而增加模組出問題的可能。如果資源有限，不要重複發明輪子。直接用經過測試的庫，在有了明確目標以及充分的資源後，可以用自己的可靠代碼來替換這個庫。</p><p>而徹底走向另一個方向，問題更嚴重 - 別人代碼的可靠性。不要習慣於所有事情都依賴於別人的代碼。在不用太多資源或者自己能掌控的情況下儘量自己寫代碼。你不需要用庫來自定義一個 TypeFaces（字體），你可以自己寫一個。</p><p>所以要記住，在這兩個極端中間平衡一下 - 不要重新創造所有事情，也不要過分依賴外部代碼。保持中立，根據自己的能力寫代碼。</p>',9)),n("p",null,[e[9]||(e[9]=t("這篇文章最早發佈在 ",-1)),i(a,{href:"https://www.whatsthatlambda.com/android/android-dev-101-things-every-beginner-must-know"},{default:s(()=>[...e[8]||(e[8]=[t("What’s That Lambda",-1)])]),_:1}),e[10]||(e[10]=t(" 上。請訪問網站閲讀更多關於 Android、Node.js、Angular.js 等等類似文章。",-1))]),e[27]||(e[27]=n("hr",null,null,-1)),n("p",null,[e[12]||(e[12]=t("via: ",-1)),i(a,{href:"https://android.jlelse.eu/12-practices-every-android-beginner-should-know-cd43c3710027"},{default:s(()=>[...e[11]||(e[11]=[t("https://android.jlelse.eu/12-practices-every-android-beginner-should-know-cd43c3710027",-1)])]),_:1})]),n("p",null,[e[16]||(e[16]=t("作者：",-1)),i(a,{href:"https://android.jlelse.eu/@nileshsingh?source=post_header_lockup"},{default:s(()=>[...e[13]||(e[13]=[t("Nilesh Singh",-1)])]),_:1}),e[17]||(e[17]=t(" 譯者：",-1)),i(a,{href:"https://github.com/zpl1025"},{default:s(()=>[...e[14]||(e[14]=[t("zpl1025",-1)])]),_:1}),e[18]||(e[18]=t(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:s(()=>[...e[15]||(e[15]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[21]||(e[21]=t("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[19]||(e[19]=[t("LCTT",-1)])]),_:1}),e[22]||(e[22]=t(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:s(()=>[...e[20]||(e[20]=[t("Linux中國",-1)])]),_:1}),e[23]||(e[23]=t(" 榮譽推出",-1))])])}const v=o(h,[["render",g]]);export{C as __pageData,v as default};
